insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'ms_music3_v1'
from (values
('117.210.c.1.A',3,'An eighth-grade band streams two professional ensembles playing the same march and notes that one phrases longer lines. They are comparing:','["interpretation of the music", "ticket prices", "hall seating", "poster designs"]'::jsonb,0,'Comparing exemplary performances reveals interpretive differences.','original'),
('117.210.c.1.A',3,'Attending a regional orchestra concert and then listening to a recording lets students contrast:','["two recipes", "live and recorded sound", "math and art", "two sports"]'::jsonb,1,'Live and recorded performances differ in sound and experience.','original'),
('117.210.c.1.B',4,'A composer indicates that a chord is built from the first, third and fifth notes of a scale. That chord is a:','["rest", "fermata", "triad", "scale"]'::jsonb,2,'A triad has three notes stacked in thirds.','original'),
('117.210.c.1.B',4,'A key signature with one sharp matches G major and also matches a minor key with the same signature, which is:','["D minor", "B minor", "A minor", "E minor"]'::jsonb,3,'The relative minor of G major is E minor.','original'),
('117.210.c.1.C',4,'In 6/8 time, the eighth note gets the beat unit and each measure has:','["six eighth-note counts", "three quarter-note counts", "eight quarter-note counts", "four quarter-note counts"]'::jsonb,0,'6/8 has six eighth-note counts.','original'),
('117.210.c.1.C',4,'A syncopated rhythm places accents:','["on every beat equally", "on weak beats or off-beats", "only on beat one", "nowhere"]'::jsonb,1,'Syncopation emphasizes unexpected beats.','original'),
('117.210.c.1.D',4,'Analyzing a piece, a student labels sections A, A'', B, A''. The A'' section is:','["a rest", "a coda", "a varied return of the A theme", "a new unrelated theme"]'::jsonb,2,'A prime shows a variation of A.','original'),
('117.210.c.1.D',4,'A fugue begins with a subject that is then imitated by other voices. This is a(n):','["monophonic form", "percussion form", "homophonic form", "polyphonic form"]'::jsonb,3,'A fugue uses imitative polyphony.','original'),
('117.210.c.1.E',3,'Proper hand position on a keyboard instrument helps prevent:','["tendon and wrist strain", "tuning problems", "rhythm errors", "page turns"]'::jsonb,0,'Good hand position protects against strain.','original'),
('117.210.c.1.E',3,'Singers stay healthy by avoiding forced loud singing and by practicing:','["straining", "good breath management", "shouting", "whispering"]'::jsonb,1,'Breath management protects the voice.','original'),
('117.210.c.2.A',4,'A tempo marked largo is:','["moderate", "lively", "very slow and broad", "very fast"]'::jsonb,2,'Largo means slow and broad.','original'),
('117.210.c.2.A',4,'A tempo marked presto is:','["moderately slow", "gradually slowing", "very slow", "very fast"]'::jsonb,3,'Presto means very fast.','original'),
('117.210.c.2.B',4,'A student notates a melody in 3/4 with a crescendo in measures 3 and 4. She should write:','["a crescendo hairpin under those measures", "a clef sign", "a coda sign", "a rest sign"]'::jsonb,0,'A hairpin shows a gradual increase in volume.','original'),
('117.210.c.2.B',3,'When notating pitch, a student places notes on the:','["bar number", "staff with the correct clef", "title line", "page margin"]'::jsonb,1,'Pitch is notated on a staff with a clef.','original'),
('117.210.c.2.C',4,'A student creates a complex rhythmic phrase that uses syncopation and mixed note values over a bass drum pulse. This phrase is more complex because it:','["avoids a beat", "uses one note", "combines varied rhythms against a steady pulse", "has no meter"]'::jsonb,2,'Complex phrases layer varied rhythms.','original'),
('117.210.c.2.C',4,'A complex melodic phrase can include:','["no rhythm", "only one repeated note", "random volume", "leaps, passing tones and a clear peak"]'::jsonb,3,'Complex melodies have shape and variety.','original'),
('117.210.c.2.D',3,'Internal hearing while reading a new line allows a performer to:','["anticipate the sound before playing", "skip the dynamics", "avoid practice", "ignore the key"]'::jsonb,0,'Inner hearing prepares accuracy.','original'),
('117.210.c.2.D',3,'A student taps the subdivision while reading a tricky rhythm. This kinesthetic response helps her:','["avoid rests", "keep accurate timing", "lose the beat", "skip repeats"]'::jsonb,1,'Tapping subdivisions supports timing.','original'),
('117.210.c.2.E',4,'Sight-reading polyphonic music requires a student to:','["play one note", "ignore the bass", "follow multiple independent lines", "read only the melody"]'::jsonb,2,'Polyphonic reading tracks several lines.','original'),
('117.210.c.2.E',4,'A student sight-reads in treble, bass and alto clefs. She is reading in:','["a single clef", "no clef", "a rhythm clef", "a variety of clefs"]'::jsonb,3,'Sight reading may involve different clefs.','original'),
('117.210.c.3.A',3,'A section leader models a round, focused tone for the group to match. She is modeling characteristic:','["instrumental or vocal timbre", "form", "tempo", "meter"]'::jsonb,0,'Modeling timbre helps the group match.','original'),
('117.210.c.3.A',3,'When a choir sings with matched vowels, the group demonstrates:','["a scattered sound", "a unified timbre", "a silent line", "a clashing tone"]'::jsonb,1,'Matching vowels unifies the timbre.','original'),
('117.210.c.3.B',4,'A student plays a snare drum rudiment with relaxed wrists to produce:','["no sound", "stiff strokes", "even, controlled rolls", "uneven bursts"]'::jsonb,2,'Relaxed technique allows control.','original'),
('117.210.c.3.B',3,'A clarinetist maintains a steady air stream and correct posture to produce:','["a cracked note", "a thin squeak", "silence", "a stable, resonant tone"]'::jsonb,3,'Posture and air produce tone.','original'),
('117.210.c.3.C',4,'A trumpeter lifts her pitch slightly after hearing she is flat against the group. She is adjusting:','["intonation", "tempo", "clef", "rest"]'::jsonb,0,'Adjusting pitch is intonation.','original'),
('117.210.c.3.C',4,'A vocalist sings with accurate rhythm and in tune while shaping long phrases. This shows independent:','["silent performance", "expressive performance", "random performance", "unplanned performance"]'::jsonb,1,'Expression combines accuracy and shaping.','original'),
('117.210.c.3.D',3,'An eighth-grade concert includes a Renaissance chorus piece, a Broadway song and a world-music arrangement. This is a:','["single genre set", "narrow list", "varied repertoire", "silent set"]'::jsonb,2,'Different styles make a varied program.','original'),
('117.210.c.3.D',3,'Choosing repertoire from different cultures lets a performer demonstrate:','["limited skill", "one dynamic", "one rhythm", "versatility in style"]'::jsonb,3,'Style variety shows versatility.','original'),
('117.210.c.3.E',4,'A sight-reading strategy is to scan the piece for key signature, meter, tempo and:','["tricky rhythms and accidentals", "the printing company", "the paper weight", "the page border"]'::jsonb,0,'Scan for challenges before playing.','original'),
('117.210.c.3.E',4,'If a mistake happens during sight-reading, the best choice is to:','["start over every time", "keep going with the group''s pulse", "stop the group", "give up"]'::jsonb,1,'Maintain the pulse.','original'),
('117.210.c.3.F',4,'A staccato marking tells the performer to play notes:','["very slow", "long and connected", "short and detached", "very loud"]'::jsonb,2,'Staccato notes are short and detached.','original'),
('117.210.c.3.F',4,'A legato marking asks the performer to play notes:','["silent", "detached", "accented", "smoothly connected"]'::jsonb,3,'Legato means smooth and connected.','original'),
('117.210.c.3.G',4,'A student writes a melody that begins in a minor key and shifts to its relative major. This adds:','["tonal contrast", "a drum solo", "silence", "a repeat sign"]'::jsonb,0,'Changing mode adds contrast.','original'),
('117.210.c.3.G',4,'A complex rhythmic phrase might include syncopation, ties and:','["no pulse", "changing note values", "silence only", "one note only"]'::jsonb,1,'Ties and varied values add complexity.','original'),
('117.210.c.4.A',3,'Singing ''The Star-Spangled Banner'' as an ensemble connects performers to:','["a pop trend", "a children''s rhyme", "a national musical tradition", "a foreign opera"]'::jsonb,2,'It is the U.S. national anthem.','original'),
('117.210.c.4.A',3,'Performing ''Texas, Our Texas'' as a class links students to:','["ancient Rome", "a world record", "a space program", "state heritage"]'::jsonb,3,'It is the Texas state song.','original'),
('117.210.c.4.B',4,'A student compares a jazz standard with a classical symphony. One clear difference is that jazz often features:','["improvisation", "no melody", "silent sections", "no rhythm"]'::jsonb,0,'Improvisation is central to jazz.','original'),
('117.210.c.4.B',4,'Comparing a spiritual and a folk ballad from different regions focuses on their:','["page counts", "origins and purposes", "sizes", "costs"]'::jsonb,1,'Origins and purposes distinguish styles.','original'),
('117.210.c.4.C',4,'Comparing music and mathematics, students note that time signatures and note values both use:','["taste", "smell", "ratios and fractions", "colors"]'::jsonb,2,'Meter and values are ratios.','original'),
('117.210.c.4.C',4,'Comparing music with physics, students learn that a shorter vibrating string produces:','["a lower pitch", "a rest", "no pitch", "a higher pitch"]'::jsonb,3,'Shorter strings vibrate faster.','original'),
('117.210.c.4.D',2,'A music teacher and a composer both have:','["music-related vocations", "no skills", "unrelated hobbies", "no jobs"]'::jsonb,0,'Teaching and composing are music careers.','original'),
('117.210.c.4.D',2,'Playing guitar at a friend''s gathering is an example of a(n):','["requirement", "avocation", "mandatory duty", "exam"]'::jsonb,1,'An avocation is a leisure pursuit.','original'),
('117.210.c.5.A',3,'A student who models good concert etiquette during a performance by others also:','["texts", "moves around", "listens attentively and avoids distractions", "chats"]'::jsonb,2,'Models of etiquette are attentive.','original'),
('117.210.c.5.A',3,'An informed listener responds to a quiet moment in a piece by:','["tapping loudly", "calling out", "clapping", "staying silent until the music ends"]'::jsonb,3,'Quiet attention shows respect.','original'),
('117.210.c.5.B',4,'Applying criteria to a performance, a student writes that the blend of the horns was balanced and the entrances were precise. She is judging:','["ensemble blend and precision", "ticket sales", "parking", "seating"]'::jsonb,0,'Blend and precision are criteria.','original'),
('117.210.c.5.B',4,'A rubric for listening might list:','["lobby decor", "tone quality, intonation and dynamics", "wardrobe", "ticket color"]'::jsonb,1,'Rubrics list musical criteria.','original'),
('117.210.c.5.C',3,'Using a metronome to track her progress on a fast passage is a:','["penalty", "distraction", "self-evaluation tool", "game"]'::jsonb,2,'A metronome shows improvement in tempo.','original'),
('117.210.c.5.C',3,'Setting short practice goals and checking them weekly is a way to:','["avoid growth", "delay work", "hide errors", "improve artistically"]'::jsonb,3,'Goals drive improvement.','original'),
('117.210.c.5.D',4,'Applying criteria to her own solo, a student compares her intonation, tone and expression against a rubric. She is:','["evaluating a personal performance", "avoiding feedback", "ignoring feedback", "judging a stranger"]'::jsonb,0,'A rubric guides self-evaluation.','original'),
('117.210.c.5.D',4,'After listening to a recording of her ensemble, a student lists strengths and areas to improve. This is:','["a rumor", "personal performance evaluation", "gossip", "a guess"]'::jsonb,1,'Listing strengths and goals evaluates performance.','original'),
('117.210.c.5.E',4,'To evaluate a performance by comparing it to an exemplar, a student listens for similarities and differences in:','["lobby art", "shoes", "tone, rhythm and style", "tickets"]'::jsonb,2,'Comparisons use musical elements.','original'),
('117.210.c.5.E',4,'A student notes that the ensemble''s balance was less even than the exemplar''s. She is evaluating its:','["length", "cost", "color", "effectiveness"]'::jsonb,3,'Balance affects effectiveness.','original'),
('117.210.c.5.F',3,'Showing a kinesthetic response to a lively march, a student might:','["step in time with the beat", "freeze", "leave", "sleep"]'::jsonb,0,'Moving in time responds to the music.','original'),
('117.210.c.5.F',3,'A cognitive response to a performance includes:','["ignoring it", "explaining the mood the composer created", "yelling", "sleeping"]'::jsonb,1,'Cognitive responses describe musical ideas.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
